@RunWith(RobolectricTestRunner::class) @Config(sdk=[34],qualifiers="w360dp-h800dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
@OptIn(ExperimentalTestApi::class)
class TallyTransferUiTest {
 @get:Rule(order=0) val initial=object:org.junit.rules.ExternalResource(){override fun before(){
  org.robolectric.Shadows.shadowOf(ctx.packageManager).addActivityIfNotPresent(android.content.ComponentName(ctx,androidx.activity.ComponentActivity::class.java))
  runBlocking{ctx.ldStore.edit{it[K.onboarded]=true;it[K.motion]=false;it[K.tallyTransfer]=false}}
 }}
 private val dispatcher=kotlinx.coroutines.test.StandardTestDispatcher()
 @get:Rule(order=1) val rule=createAndroidComposeRule<androidx.activity.ComponentActivity>(effectContext=dispatcher)
 private val ctx get()=ApplicationProvider.getApplicationContext<LdApp>();private val n="+919876543210"
 private fun settle(){org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();dispatcher.scheduler.runCurrent();rule.runOnUiThread{androidx.compose.runtime.snapshots.Snapshot.sendApplyNotifications()};rule.mainClock.autoAdvance=false;rule.mainClock.advanceTimeBy(800);dispatcher.scheduler.runCurrent();rule.waitForIdle()}
 private fun await(tag:String){rule.waitUntil(15000){settle();rule.onAllNodesWithTag(tag,true).fetchSemanticsNodes().isNotEmpty()}}
 private fun scrollTo(tag:String){rule.mainClock.autoAdvance=true;repeat(5){val n=rule.onNodeWithTag(tag,true).fetchSemanticsNode();val root=rule.onRoot().fetchSemanticsNode();val delta=n.positionInRoot.y+n.size.height/2f-root.size.height/2f
 if(n.positionInRoot.y>=75&&n.positionInRoot.y+n.size.height<root.size.height-20){rule.mainClock.autoAdvance=false;settle();return}
 rule.onNode(SemanticsMatcher.keyIsDefined(androidx.compose.ui.semantics.SemanticsProperties.VerticalScrollAxisRange)).performSemanticsAction(androidx.compose.ui.semantics.SemanticsActions.ScrollBy){it(0f,delta)};rule.waitForIdle()};rule.mainClock.autoAdvance=false;settle()}
 private fun click(tag:String){scrollTo(tag);rule.onNodeWithTag(tag,true).assertIsEnabled().performClick();settle()}
 private var focus:androidx.compose.ui.focus.FocusManager?=null
 private fun waitFor(f:()->Boolean){rule.waitUntil(15000){settle();f()}}
 private fun show(night:Boolean=false,notes:Boolean=false,enabled:Boolean=true,direct:Boolean=false){settle();runBlocking{ctx.ldStore.edit{it[K.onboarded]=true;it[K.theme]=if(night)"midnight"else"daylight";it[K.fontScale]=if(night)1.4f else 1f;it[K.callTally]=false;it[K.tallyTransfer]=enabled}};waitFor{LdApp.settings.value.let{it.theme==(if(night)"midnight"else"daylight")&&it.fontScale==(if(night)1.4f else 1f)&&!it.callTally&&it.tallyTransfer==enabled}};rule.runOnUiThread{val host=androidx.compose.ui.platform.ComposeView(rule.activity);host.setContent{focus=androidx.compose.ui.platform.LocalFocusManager.current;LdThemeHost{if(notes)Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(16.dp)){NotesSheet(n,"Support",{})}else if(direct)TallyTransferWorkspace(sample,{closed=true},{applied=it})else CallTallyWorkspace({})}};rule.activity.setContentView(host)};settle()}
 private fun input(tag:String,s:String){scrollTo(tag);rule.onNode(hasSetTextAction() and hasAnyAncestor(hasTestTag(tag)),true).performTextReplacement(s);settle()}
 @After fun reset(){rule.runOnUiThread{focus?.clearFocus(force=true);androidx.compose.runtime.snapshots.Snapshot.sendApplyNotifications()};settle();rule.runOnUiThread{(rule.activity.findViewById<android.view.ViewGroup>(android.R.id.content)).removeAllViews()};runBlocking{ctx.ldStore.edit{it[K.fontScale]=1f;it[K.callTally]=false;it[K.tallyTransfer]=false}}}
 private fun add(name:String,value:String="0"){input("tally_name",name);input("tally_value",value);click("tally_apply")}
 private val sample=listOf(CallTally.Item("a","Rice premium large family pack bags with matching unit",24),CallTally.Item("b","Sugar bags",12),CallTally.Item("c","Reserved bags",5))
 private var applied:TallyTransfer.Preview?=null;private var closed=false
 private fun dialog(tag:String){rule.onNodeWithTag(tag,true).performClick();settle()}

 private fun allocation(s:String="6",t:String="3"){click("transfer_source_0");input("transfer_input_1",s);if(t.isNotEmpty())input("transfer_input_2",t);click("transfer_preview")}
 @Test fun defaultOffHidesEntry(){show(enabled=false);rule.onAllNodesWithTag("tally_transfer_open",true).assertCountEquals(0);assertFalse(LdSettings().tallyTransfer)}
 @Test fun insufficientCountersCannotPick(){show();click("tally_transfer_open");await("transfer_empty");rule.onAllNodesWithTag("transfer_preview",true).assertCountEquals(0)}
 @Test fun previewCancelAndExplicitConfirm(){show(direct=true);allocation();rule.onNodeWithTag("transfer_change_0",true).assertTextEquals("24 → 15");rule.onNodeWithTag("transfer_change_1",true).assertTextEquals("12 → 18");rule.onNodeWithTag("transfer_change_2",true).assertTextEquals("5 → 8");rule.onNodeWithTag("transfer_total",true).assertTextEquals("2 destinations · raw total 41 → 41");assertNull(applied);click("transfer_apply");dialog("transfer_cancel");assertNull(applied);click("transfer_apply");dialog("transfer_confirm");assertEquals(listOf(15L,18L,8L),applied!!.after.map{it.value})}
 @Test fun blankDestinationUnchanged(){show(direct=true);allocation(t="");rule.onAllNodesWithTag("transfer_change_2",true).assertCountEquals(0);click("transfer_apply");dialog("transfer_confirm");assertEquals(sample.last(),applied!!.after.last())}
 @Test fun sourceChangeClearsInputsAndPreview(){show(direct=true);allocation();click("transfer_source_1");rule.onAllNodesWithTag("transfer_apply",true).assertCountEquals(0);rule.onAllNodesWithTag("transfer_input_1",true).assertCountEquals(0);rule.onNode(hasSetTextAction() and hasAnyAncestor(hasTestTag("transfer_input_2")),true).assertTextEquals("");rule.onNodeWithTag("transfer_preview",true).assertIsNotEnabled()}
 @Test fun inputEditInvalidatesPreview(){show(direct=true);allocation();input("transfer_input_1","7");rule.onAllNodesWithTag("transfer_apply",true).assertCountEquals(0);click("transfer_preview");rule.onNodeWithTag("transfer_change_0",true).assertTextEquals("24 → 14")}
 @Test fun shortageAndMalformedNoPartialApply(){show(direct=true);allocation("23","2");rule.onNodeWithTag("transfer_error",true).assertTextContains("Whole transfer refused",substring=true);rule.onAllNodesWithTag("transfer_apply",true).assertCountEquals(0);assertNull(applied);input("transfer_input_1","1.5");click("transfer_preview");rule.onNodeWithTag("transfer_error",true).assertExists();assertNull(applied)}
 @Test fun returnKeepsBoardEditorAndDiscardsTransferDraft(){show();add("Bags","24");add("Packed bags","5");input("tally_name","Keep unfinished");click("tally_transfer_open");click("transfer_source_0");input("transfer_input_1","3");click("transfer_preview");click("transfer_back");rule.onNodeWithTag("tally_total",true).assertTextEquals("29");rule.onNode(hasSetTextAction() and hasAnyAncestor(hasTestTag("tally_name")),true).assertTextEquals("Keep unfinished");click("tally_transfer_open");rule.onAllNodesWithTag("transfer_selected",true).assertCountEquals(0)}
 @Test fun oneUndoRedoPreservesStepClearsEditor(){show();add("Bags","24");add("Packed bags","5");input("tally_step","5");input("tally_name","Unfinished");click("tally_transfer_open");click("transfer_source_0");input("transfer_input_1","6");click("transfer_preview");click("transfer_apply");dialog("transfer_confirm");rule.onNodeWithTag("tally_quantity_0",true).assertTextEquals("18");rule.onNodeWithTag("tally_quantity_1",true).assertTextEquals("11");rule.onNodeWithTag("tally_editor",true).assertTextEquals("New counter");click("tally_undo");rule.onNodeWithTag("tally_quantity_0",true).assertTextEquals("24");rule.onNodeWithTag("tally_quantity_1",true).assertTextEquals("5");click("tally_redo");rule.onNodeWithTag("tally_quantity_0",true).assertTextEquals("18");click("tally_plus_0");rule.onNodeWithTag("tally_quantity_0",true).assertTextEquals("23")}
 @Test fun sourceReplacementInvalidatesSelectionPreviewAndConfirmation(){show(direct=true);val src=androidx.compose.runtime.mutableStateOf(sample);rule.runOnUiThread{val host=androidx.compose.ui.platform.ComposeView(rule.activity);host.setContent{LdThemeHost{TallyTransferWorkspace(src.value,{}, {applied=it})}};rule.activity.setContentView(host)};settle();allocation();click("transfer_apply");rule.runOnUiThread{src.value=sample.dropLast(1)};settle();rule.onAllNodesWithTag("transfer_confirm",true).assertCountEquals(0);rule.onAllNodesWithTag("transfer_apply",true).assertCountEquals(0);rule.onAllNodesWithTag("transfer_selected",true).assertCountEquals(0);assertNull(applied)}
 @Test fun settingsPersistsFinderAndPixels(){show(enabled=false);assertTrue(SettingsFinder.all.any{it.id=="tally-transfer"&&it.route=="calltally"});rule.runOnUiThread{val host=androidx.compose.ui.platform.ComposeView(rule.activity);host.setContent{LdThemeHost{CallTallyPage({})}};rule.activity.setContentView(host)};settle();rule.onNodeWithText("Tally quantity transfer").performClick();waitFor{LdApp.settings.value.tallyTransfer};saveShot(rule,"TRANSFER441-settings");click("tally_settings_open");rule.onNodeWithTag("tally_transfer_open",true).assertExists()}
 @Test fun daySourcePreviewAndConfirmationPixels(){show(direct=true);click("transfer_source_0");scrollTo("transfer_source_title");saveShot(rule,"TRANSFER441-day-source");input("transfer_input_1","6");input("transfer_input_2","3");click("transfer_preview");scrollTo("transfer_preview_state");saveShot(rule,"TRANSFER441-day-preview");scrollTo("transfer_apply");saveShot(rule,"TRANSFER441-day-changes");click("transfer_apply");saveDialogShot("TRANSFER441-day-confirm",0xffedf1ff)}
 @Test fun nightLargeAllocationAndPreviewPixels(){show(night=true,direct=true);click("transfer_source_0");input("transfer_input_1","6");input("transfer_input_2","3");scrollTo("transfer_selected");saveShot(rule,"TRANSFER441-night-allocation");click("transfer_preview");scrollTo("transfer_preview_state");saveShot(rule,"TRANSFER441-night-preview");scrollTo("transfer_apply");saveShot(rule,"TRANSFER441-night-changes");click("transfer_apply");saveDialogShot("TRANSFER441-night-confirm",0xff0d1320)}
 @Test fun noClipboardFileOrCallEffectsAndSessionDiscarded(){show();val clipboard=ctx.getSystemService(android.content.Context.CLIPBOARD_SERVICE)as android.content.ClipboardManager;clipboard.setPrimaryClip(android.content.ClipData.newPlainText("existing","Keep clipboard"));val before=ctx.filesDir.walkTopDown().filter{it.isFile&&it.extension=="json"}.associate{it.path to it.readBytes()};add("Bags","24");add("Packed bags","5");click("tally_transfer_open");click("transfer_source_0");input("transfer_input_1","6");click("transfer_preview");click("transfer_apply");dialog("transfer_confirm");before.forEach{(f,b)->assertArrayEquals(b,File(f).readBytes())};assertEquals("Keep clipboard",clipboard.primaryClip!!.getItemAt(0).text.toString());assertNull(org.robolectric.Shadows.shadowOf(rule.activity).nextStartedActivity);show();rule.onNodeWithTag("tally_total",true).assertTextEquals("0")}
 @Test fun callSheetKeepsNoteDraftAndNeverSavesBoard(){show(notes=true);rule.onNode(hasSetTextAction()).performTextInput("Keep note draft");runBlocking{ctx.repo.set(K.callTally,true)};await("call_tally_open");click("call_tally_open");add("Bags","24");add("Packed bags","5");click("tally_transfer_open");click("transfer_source_0");input("transfer_input_1","6");click("transfer_preview");click("transfer_apply");dialog("transfer_confirm");rule.onNodeWithTag("tally_quantity_0",true).assertTextEquals("18");click("tally_back");dialog("tally_confirm");rule.onNodeWithText("Keep note draft").assertExists();click("call_tally_open");rule.onNodeWithTag("tally_total",true).assertTextEquals("0")}
 @Test fun overflowRefusesAllAndLastOfTwelveDestinationsReachable(){show(direct=true);val src=androidx.compose.runtime.mutableStateOf(listOf(CallTally.Item("s","Source bags",24),CallTally.Item("t","Full bags",CallTally.MAX_VALUE)));rule.runOnUiThread{val host=androidx.compose.ui.platform.ComposeView(rule.activity);host.setContent{LdThemeHost{TallyTransferWorkspace(src.value,{}, {applied=it})}};rule.activity.setContentView(host)};settle();click("transfer_source_0");input("transfer_input_1","1");click("transfer_preview");rule.onNodeWithTag("transfer_error",true).assertTextContains("Whole transfer refused",substring=true);assertNull(applied);rule.runOnUiThread{src.value=(0..11).map{CallTally.Item("$it","Bags $it",if(it==0)24 else 0)}};settle();click("transfer_source_0");input("transfer_input_11","24");click("transfer_preview");click("transfer_apply");dialog("transfer_confirm");assertEquals(0L,applied!!.after.first().value);assertEquals(24L,applied!!.after.last().value);assertEquals(24L,CallTally.total(applied!!.after))}
}
